    @Volatile
    private var cachedWordSet: Set<String>? = null

    @Volatile
    private var cachedArabicMap: Map<String, String>? = null

    private fun ensureLoaded() {
        if (cachedWordSet != null && cachedArabicMap != null) return
        synchronized(this) {
            if (cachedWordSet != null && cachedArabicMap != null) return
            val set = HashSet<String>(4096)
            val arabicMap = HashMap<String, String>(1024)

            RAW_WORDS.split(' ').forEach { token ->
                val cleaned = token.trim()
                if (cleaned.length >= 3) {
                    set.add(cleaned)
                }
            }

            arabicMap.putAll(EXTRA_ARABIC_TRANSLATIONS)

            WordGameRepository.levels.forEach { level ->
                val mainUpper = level.mainWord.uppercase()
                if (mainUpper.length >= 3) {
                    set.add(mainUpper)
                    arabicMap.putIfAbsent(mainUpper, level.arabic)
                }
                level.extractedWords.forEach { item ->
                    val wordUpper = item.word.uppercase()
                    if (wordUpper.length >= 3) {
                        set.add(wordUpper)
                        arabicMap.putIfAbsent(wordUpper, item.arabic)
                    }
                }
            }

            cachedWordSet = set
            cachedArabicMap = arabicMap
        }
    }

    fun warmUp() {
        ensureLoaded()
    }

    fun isValidEnglishWord(word: String): Boolean {
        val normalized = word.trim().uppercase()
        if (normalized.length < 3) return false
        ensureLoaded()
        return cachedWordSet?.contains(normalized) == true
    }

    fun getArabicTranslation(word: String): String? {
        val normalized = word.trim().uppercase()
        if (normalized.length < 3) return null
        ensureLoaded()
        return cachedArabicMap?.get(normalized)
    }
